package com.yeyamo_mobile.api.culture_service.domain;
import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="language_lesson_items") public class LanguageLessonItem{@Id private UUID id;@Column(name="lesson_id",nullable=false)private UUID lessonId;@Column(nullable=false)private String phrase;@Column(nullable=false)private String translation;private String transcription;private String phonetic;@Column(name="audio_media_id")private UUID audioMediaId;@Column(name="image_media_id")private UUID imageMediaId;@Column(name="cultural_context",columnDefinition="TEXT")private String culturalContext;@Column(nullable=false)private int difficulty;@Column(columnDefinition="TEXT")private String examples;@Column(name="display_order",nullable=false)private int displayOrder;protected LanguageLessonItem(){}public UUID getId(){return id;}public UUID getLessonId(){return lessonId;}public String getPhrase(){return phrase;}public String getTranslation(){return translation;}public String getTranscription(){return transcription;}public String getPhonetic(){return phonetic;}public UUID getAudioMediaId(){return audioMediaId;}public UUID getImageMediaId(){return imageMediaId;}public String getCulturalContext(){return culturalContext;}public int getDifficulty(){return difficulty;}public String getExamples(){return examples;}public int getDisplayOrder(){return displayOrder;}}
